package cn.vie.vibe.gallery.api;
import cn.vie.vibe.gallery.application.*; import cn.vie.vibe.gallery.domain.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/photos/tasks") public class PhotoTaskController { private final PhotoProcessingTaskRepository tasks; private final TenantContextResolver context; public PhotoTaskController(PhotoProcessingTaskRepository t,TenantContextResolver c){tasks=t;context=c;} @GetMapping("/{taskId}") public TaskResponse get(@PathVariable UUID taskId){PhotoProcessingTask t=tasks.findById(context.requireContext().tenantId(),taskId).orElseThrow(()->new DomainException("TASK_NOT_FOUND","Task not found"));return new TaskResponse(t.id(),t.status(),t.attempts(),t.errorMessage());} public record TaskResponse(UUID id,TaskStatus status,int attempts,String errorMessage){} }
